<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('communication','view');
global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];$q=$conn->prepare("SELECT * FROM sms_gateways WHERE tenant_id=? ORDER BY id DESC");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}
$pageTitle='SMS Gateways';require_once '../includes/header.php';?><div class="dashboard-card"><div class="page-header"><div><h2>SMS Gateway</h2><p>Provider configuration, sender identity, status and balance.</p></div></div><div class="table-responsive"><table><thead><tr><th>Name</th><th>Provider</th><th>Sender</th><th>Status</th><th>Balance</th><th>Verified</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?=e($x['name'])?></td><td><?=e($x['provider'])?></td><td><?=e($x['sender_id']??'—')?></td><td><?=e($x['status'])?></td><td><?=e($x['balance']!==null?formatMoney($x['balance']):'—')?></td><td><?=e($x['last_verified_at']??'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No SMS gateways configured.</td></tr><?php endif;?></tbody></table></div></div><?php require_once '../includes/footer.php';?>